export const policyPieces=['Refundable','hotel bookings','can be cancelled','until 48 hours','before check-in.','Breakfast','starts at','07:00.'];
export function cutPolicy(cut){
 const chunks=[policyPieces.slice(0,cut),policyPieces.slice(cut)];
 const selected=chunks.find(c=>c.includes('until 48 hours'));
 return {chunks,selected,fits:selected.length<=5,complete:selected.includes('Refundable')&&selected.includes('before check-in.')};
}
export function mountChunkBench(host){
 host.innerHTML=`<details class="mini-bench"><summary>Next experiment: cut a document without losing the rule <span>2 min</span></summary><div class="bench-body"><span class="eyebrow">CHUNKING / KEEP MEANING TOGETHER</span><h2>Where would you cut?</h2><p>RAG usually retrieves passages, not whole documents. A useful chunk keeps a rule and its conditions together. Tap a cut point between phrases, or move the slider, to split this tiny hotel policy.</p><div class="paper-strip" id="chunk-paper"></div><label for="chunk-cut">Cut after phrase <output id="chunk-position"></output></label><input id="chunk-cut" type="range" min="1" max="7" value="3"><div class="chunk-preview" id="chunk-preview"></div><p class="bench-goal"><b>Your goal:</b> keep the full refund rule in one chunk that fits five phrase units. Leave breakfast out.</p><button id="chunk-test" class="primary">Try retrieving the rule</button><p id="chunk-feedback" role="status"></p><small>Phrase units make the cut visible here. Production chunking usually uses tokens and may preserve headings or overlap neighbouring passages.</small></div></details>`;
 const slider=host.querySelector('#chunk-cut');
 function update(){const cut=+slider.value,{chunks,selected,fits}=cutPolicy(cut);host.querySelector('#chunk-position').textContent=cut;host.querySelector('#chunk-paper').innerHTML=policyPieces.map((p,i)=>'<span>'+p+'</span>'+(i<policyPieces.length-1?'<button class="cut-point '+(i===cut-1?'selected-cut':'')+'" data-cut="'+(i+1)+'" aria-label="Cut after phrase '+(i+1)+'" aria-pressed="'+(i===cut-1)+'">&#9986;</button>':'')).join('');host.querySelector('#chunk-preview').innerHTML=chunks.map((c,i)=>'<article class="'+(c===selected?'selected-chunk':'')+'"><span>CHUNK '+(i+1)+' / '+c.length+' units</span><p>'+c.join(' ')+'</p><small>'+(c===selected?(fits?'Retrieved: contains the 48-hour rule':'Retrieved, but too large for the window'):'Not retrieved in this example')+'</small></article>').join('');host.querySelector('#chunk-feedback').textContent='';host.querySelectorAll('[data-cut]').forEach(button=>button.onclick=()=>{slider.value=button.dataset.cut;update();host.querySelector('[data-cut="'+slider.value+'"]').focus({preventScroll:true});});}
 slider.oninput=update;host.querySelector('#chunk-test').onclick=()=>{const r=cutPolicy(+slider.value);host.querySelector('#chunk-feedback').textContent=!r.fits?'The passage has the answer, but is too large. Move the cut before the breakfast information.':!r.complete?'The retrieved passage lost part of the rule. Keep the refundable condition and the check-in deadline together.':'Solved. The rule, condition and deadline travel together. Smaller is useful only when meaning survives.';};update();
}
